async function compile_gemini_chat_hub_plugin_json(params, userSettings, resources) {
  function generateUUID() {
    try {
      return crypto.randomUUID();
    } catch (e) {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0;
        const v = c === 'x' ? r : (r & 0x03 | 0x08);
        return v.toString(16);
      });
    }
  }

  function ensureString(val) {
    if (val === undefined || val === null) return "";
    if (typeof val === "object") {
      return JSON.stringify(val, null, 2);
    }
    return String(val);
  }

  try {
    const pluginTitle = params.title || params.name || "Custom Plugin";
    const pluginId = params.id || pluginTitle.toLowerCase().replace(/[^a-z0-9_]/g, "_");
    const pluginUUID = generateUUID();

    const finalUserSettings = [];

    if (params.userSettings && Array.isArray(params.userSettings)) {
      params.userSettings.forEach(setting => {
        const s = {
          name: setting.name,
          type: setting.type || "text",
          label: setting.label || setting.name,
          required: setting.required !== false,
          description: setting.description || ""
        };
        if (setting.placeholder) s.placeholder = setting.placeholder;
        if (setting.type === "enum" && (setting.enum || setting.values)) {
          s.values = setting.enum || setting.values;
        }
        if (setting.defaultValue !== undefined) {
          s.defaultValue = setting.defaultValue;
        }
        if (setting.vaultSecret) {
          s.vaultSecret = setting.vaultSecret;
        }
        finalUserSettings.push(s);
      });
    }

    const pluginFunctions = [];
    if (params.functions && Array.isArray(params.functions)) {
      params.functions.forEach(fn => {
        const funcUUID = generateUUID();

        const requiredParams = [];
        const properties = {};

        if (fn.parameters && Array.isArray(fn.parameters)) {
          fn.parameters.forEach(p => {
            properties[p.name] = {
              type: p.type || "string",
              description: p.description || ""
            };
            if (p.type === "array" && p.itemsType) {
              properties[p.name].items = { type: p.itemsType };
            }
            if ((p.enum || p.values) && Array.isArray(p.enum || p.values)) {
              properties[p.name].enum = p.enum || p.values;
            }
            if (p.required) {
              requiredParams.push(p.name);
            }
          });
        }

        const openaiSpec = {
          name: fn.name,
          description: fn.description || "",
          parameters: {
            type: "object",
            properties: properties
          }
        };

        if (requiredParams.length > 0) {
          openaiSpec.parameters.required = requiredParams;
        }

        const compiledFunc = {
          id: funcUUID,
          name: fn.label || fn.name,
          implementationType: fn.implementationType || "javascript",
          outputType: fn.outputType || "respond_to_ai",
          openaiSpec: openaiSpec,
          permissions: Array.isArray(fn.permissions) && fn.permissions.length > 0 
            ? fn.permissions 
            : ["local_storage", "workspace", "vault"]
        };

        if (fn.implementationType === "javascript") {
          compiledFunc.code = fn.code || "";
        } else if (fn.implementationType === "http") {
          const headersStr = ensureString(fn.httpHeaders);
          const bodyStr = ensureString(fn.httpBody);
          const hasHeaders = !!headersStr && headersStr.trim() !== "" && headersStr.trim() !== "{}";
          const hasBody = !!bodyStr && bodyStr.trim() !== "";

          compiledFunc.httpAction = {
            id: generateUUID(),
            url: fn.httpUrl || "",
            name: "",
            method: (fn.httpMethod || "GET").toUpperCase(),
            hasHeaders: hasHeaders,
            requestHeaders: hasHeaders ? headersStr : "",
            hasBody: hasBody,
            requestBody: hasBody ? bodyStr : "",
            requestBodyFormat: fn.requestBodyFormat || "json",
            save_to_workspace: !!fn.saveToWorkspace,
            workspace_filename: fn.workspaceFilename || ""
          };

          if (fn.templateString) {
            compiledFunc.httpAction.hasResultTransform = true;
            compiledFunc.httpAction.resultTransform = {
              engine: fn.transformEngine || "handlebars",
              templateString: fn.templateString
            };
          }
        }

        pluginFunctions.push(compiledFunc);
      });
    }

    const localStorageConfig = params.localStorage !== undefined 
      ? params.localStorage 
      : { enabled: true, initialData: {} };

    const workspaceAccessConfig = params.workspaceAccess !== undefined 
      ? params.workspaceAccess 
      : { enabled: true, allowedDirectories: ["in", "out", "tmp"] };

    const vaultSecretsList = Array.isArray(params.vaultSecrets) 
      ? params.vaultSecrets 
      : [];

    const finalPlugin = { 
      id: pluginId,
      uuid: pluginUUID,
      emoji: params.emoji || "⚙️",
      title: pluginTitle,
      name: pluginTitle,
      iconURL: params.iconURL || "https://api.iconify.design/lucide:blocks.svg",
      icon_url: params.iconURL || "https://api.iconify.design/lucide:blocks.svg",
      version: params.version || "2.0.0",
      author: params.author || "Gemini Chat Hub",
      userSettings: finalUserSettings,
      user_settings: finalUserSettings,
      pluginFunctions: pluginFunctions,
      functions: pluginFunctions,
      contextPrompt: params.contextPrompt || "",
      context_prompt: params.contextPrompt || "",
      localStorage: localStorageConfig,
      workspaceAccess: workspaceAccessConfig,
      vaultSecrets: vaultSecretsList,
      overviewMarkdown: params.overviewMarkdown || ("# " + pluginTitle + "\n\nCustom Gemini Chat Hub plugin."),
      authenticationType: "AUTH_TYPE_NONE"
    };

    const jsonString = JSON.stringify(finalPlugin, null, 2);

    return "### ⚙️ Gemini Chat Hub Plugin Compiled Successfully!\n" +
      "Here is the JSON payload for **" + finalPlugin.title + "**, ready to import into Gemini Chat Hub.\n\n" +
      "#### Capabilities Enabled:\n" +
      "- 💾 **Persistent Local Storage**: " + (finalPlugin.localStorage?.enabled ? "Active (PostgreSQL + Disk Mirroring)" : "Disabled") + "\n" +
      "- 🖥️ **Workspace Code Execution Bridge**: " + (finalPlugin.workspaceAccess?.enabled ? "Active (/workspace/in, out, tmp)" : "Disabled") + "\n" +
      "- 🔑 **Secret Vault Access**: " + (finalPlugin.vaultSecrets?.length ? finalPlugin.vaultSecrets.join(", ") : "None requested") + "\n" +
      "- ⚡ **Node.js VM Execution**: Direct server fetch (Zero CORS restrictions, 90s timeout)\n\n" +
      "To install this in Gemini Chat Hub:\n" +
      "1. Hover over the JSON code block below and click **Copy**.\n" +
      "2. Open the **Plugins** dialog (click the puzzle/blocks icon in the header or sidebar).\n" +
      "3. Switch to the **Import Plugin JSON** tab.\n" +
      "4. Paste the JSON and click **Import and Register Plugin**.\n" +
      "5. If User Settings or Vault Secrets are configured, click the **Settings** gear to configure them!\n\n" +
      "\n\n" +
      String.fromCharCode(96).repeat(3) + "json\n" + jsonString + "\n" + String.fromCharCode(96).repeat(3) + "\n\n" +
      "---\n*Compiled using Gemini Chat Hub Plugin Generator.*

  } catch (err) {
    return "### ❌ Compilation Error\nAn error occurred while compiling your plugin:\n\n" + String.fromCharCode(96).repeat(3) + "\n" + err.message + "\n" + String.fromCharCode(96).repeat(3) + "\n";
  }
}

